export interface Tokens {
  accessToken: string;
  expiresAt: number;
}

export function needsRefresh(tokens: Tokens, skewMs = 30_000): boolean {
  return Date.now() + skewMs >= tokens.expiresAt;
}

export async function refresh(fetchImpl: typeof fetch, refreshToken: string): Promise<Tokens> {
  const res = await fetchImpl("https://auth.example.com/oauth/token", {
    method: "POST",
    body: new URLSearchParams({ grant_type: "refresh_token", refresh_token: refreshToken }),
  });
  if (!res.ok) throw new Error(`refresh failed: ${res.status}`);
  const body = (await res.json()) as { access_token: string; expires_in: number };
  return { accessToken: body.access_token, expiresAt: Date.now() + body.expires_in * 1000 };
}

